/**
 * Writes a real, valid PDF containing a bank statement laid out in columns.
 *
 * Hand-built rather than generated by a library, because the point is to
 * exercise pdf.js text extraction with genuine positioned text runs: the parser
 * groups items by rounded Y and orders them by X, so the columns have to be
 * separate text-showing operations at real coordinates, not one long string.
 */
import fs from "node:fs";

function buildPdf(pages) {
  const objects = [];
  const add = (body) => {
    objects.push(body);
    return objects.length; // 1-indexed object number
  };

  const fontNum = 4; // fixed below
  const contentNums = [];
  const pageNums = [];

  // Reserve 1 catalog, 2 pages, 3.. pages/contents. Simpler: build content
  // streams first, then pages, then the pages node, then the catalog.
  const contentBodies = pages.map((lines) => {
    let s = "BT\n/F1 9 Tf\n";
    for (const { x, y, text, size } of lines) {
      const escaped = String(text)
        .replace(/\\/g, "\\\\")
        .replace(/\(/g, "\\(")
        .replace(/\)/g, "\\)");
      s += `/F1 ${size || 9} Tf\n1 0 0 1 ${x} ${y} Tm\n(${escaped}) Tj\n`;
    }
    s += "ET";
    return s;
  });

  // Object layout: 1 catalog, 2 pages node, 3 font, then per page: page obj +
  // content obj.
  const catalogNum = 1;
  const pagesNum = 2;
  const fontObjNum = 3;
  let next = 4;
  for (let i = 0; i < pages.length; i++) {
    pageNums.push(next++);
    contentNums.push(next++);
  }

  const parts = new Map();
  parts.set(catalogNum, `<< /Type /Catalog /Pages ${pagesNum} 0 R >>`);
  parts.set(
    pagesNum,
    `<< /Type /Pages /Kids [${pageNums.map((n) => `${n} 0 R`).join(" ")}] /Count ${pages.length} >>`,
  );
  parts.set(
    fontObjNum,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
  );
  for (let i = 0; i < pages.length; i++) {
    parts.set(
      pageNums[i],
      `<< /Type /Page /Parent ${pagesNum} 0 R /MediaBox [0 0 595 842] ` +
        `/Resources << /Font << /F1 ${fontObjNum} 0 R >> >> /Contents ${contentNums[i]} 0 R >>`,
    );
    const body = contentBodies[i];
    parts.set(
      contentNums[i],
      `<< /Length ${Buffer.byteLength(body, "latin1")} >>\nstream\n${body}\nendstream`,
    );
  }

  const total = next - 1;
  let pdf = "%PDF-1.4\n";
  const offsets = [];
  for (let n = 1; n <= total; n++) {
    offsets[n] = Buffer.byteLength(pdf, "latin1");
    pdf += `${n} 0 obj\n${parts.get(n)}\nendobj\n`;
  }
  const xrefStart = Buffer.byteLength(pdf, "latin1");
  pdf += `xref\n0 ${total + 1}\n0000000000 65535 f \n`;
  for (let n = 1; n <= total; n++) {
    pdf += `${String(offsets[n]).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${total + 1} /Root ${catalogNum} 0 R >>\nstartxref\n${xrefStart}\n%%EOF\n`;

  void fontNum;
  void add;
  return Buffer.from(pdf, "latin1");
}

// A Monzo current account statement, laid out the way a real one is: a date
// column, a description column, and right-aligned money columns.
const COL = { date: 50, desc: 130, out: 400, in: 480, bal: 530 };
const rows = [
  ["01/07/2026", "COSTA COFFEE LONDON", "3.99", "", "1,246.01"],
  ["02/07/2026", "TESCO STORES 3421", "42.50", "", "1,203.51"],
  ["03/07/2026", "MONTHLY RENT PAYMENT", "1,250.00", "", "-46.49"],
  ["04/07/2026", "ACME LTD SALARY", "", "2,500.00", "2,453.51"],
  ["05/07/2026", "NETFLIX.COM", "8.99", "", "2,444.52"],
  ["08/07/2026", "SAINSBURYS LOCAL 4412", "18.75", "", "2,425.77"],
  ["09/07/2026", "TFL TRAVEL CHARGE", "7.60", "", "2,418.17"],
  ["10/07/2026", "THAMES WATER UTILITIES", "32.14", "", "2,386.03"],
  ["11/07/2026", "SPOTIFY PREMIUM", "11.99", "", "2,374.04"],
  ["15/07/2026", "AMAZON MARKETPLACE UK", "56.30", "", "2,317.74"],
  ["17/07/2026", "HMRC TAX REBATE", "", "142.60", "2,460.34"],
  ["18/07/2026", "SHELL FILLING STATION", "61.02", "", "2,399.32"],
  ["20/07/2026", "BRITISH GAS ENERGY", "78.44", "", "2,320.88"],
  ["21/07/2026", "WAITROSE AND PARTNERS 12", "63.18", "", "2,257.70"],
];

const lines = [];
let y = 790;
const put = (x, text, size) => lines.push({ x, y, text, size });

put(COL.date, "Monzo Bank Limited", 14);
y -= 18;
put(COL.date, "Current Account Statement");
y -= 14;
put(COL.date, "Account 12345678   Sort code 04-00-04");
y -= 14;
put(COL.date, "Statement period 01 July 2026 to 31 July 2026");
y -= 26;
put(COL.date, "Date");
put(COL.desc, "Description");
put(COL.out, "Money Out");
put(COL.in, "Money In");
put(COL.bal, "Balance");
y -= 16;
put(COL.desc, "Opening balance");
put(COL.bal, "1,250.00");
y -= 15;

for (const [date, desc, out, money_in, bal] of rows) {
  put(COL.date, date);
  put(COL.desc, desc);
  if (out) put(COL.out, out);
  if (money_in) put(COL.in, money_in);
  put(COL.bal, bal);
  y -= 15;
}

y -= 20;
put(COL.date, "Closing balance", 10);
put(COL.bal, "2,257.70", 10);

const out = process.argv[2];
fs.writeFileSync(out, buildPdf([lines]));
console.log("wrote", out, fs.statSync(out).size, "bytes,", rows.length, "transactions");
